sources.flags.py:
FLAGS = {"parent": True, "child": True, "retired": False}
REQUIRES = {"child": "parent"}
def evaluate(name):
    parent = REQUIRES.get(name)
    return FLAGS[name] and (parent is None or evaluate(parent))

